// Anchors a WebCodecs VideoFrame.timestamp (relative to an unspecified
// internal media clock, NOT the Unix epoch) to wall-clock epoch
// microseconds, then ratchets it to guarantee strict monotonicity across
// stream pauses, re-attaches, and stop()/start() restarts. Extracted from
// the renderer's frame loop into its own module so the anchor + ratchet
// math is unit-testable in plain Node — renderer/index.js itself needs
// OffscreenCanvas/MediaStreamTrackProcessor, which don't exist there.
//
// Android/iOS/Linux each apply an equivalent one-time boot/mach-to-epoch
// offset before a camera frame's timestamp reaches the graph
// (SmartSpectraVitalsProcessor.kt, avfoundation_camera_source.mm,
// v4l2_camera_source.cc); this is the Electron/WebCodecs binding's
// counterpart, so Metrics.timestamp is wall-clock-comparable across every
// binding instead of only self-consistent within one Electron session.

'use strict';

class FrameTimestampAnchor {
    constructor() {
        // Set from the first frame passed to next(); null means "not yet
        // anchored". Persists for the anchor's lifetime (kept on the
        // instance, not recomputed per stop()/start(), the same reasoning
        // as _lastFrameTs below — VideoFrame.timestamp's clock domain is
        // page-navigation-relative, not per-stream).
        this._epochOffsetUs = null;
        // Last timestamp handed out, for the monotonic ratchet.
        this._lastFrameTs = 0n;
    }

    /**
     * @param {number|bigint} rawTimestampUs VideoFrame.timestamp — already
     *   microseconds, but in its own media-clock domain.
     * @param {number} [nowMs] Wall-clock epoch milliseconds at the moment of
     *   the first call. Defaults to Date.now(); overridable so callers (and
     *   tests) can pin a deterministic anchor.
     * @returns {bigint} Epoch microseconds, strictly greater than every
     *   previous value returned by this instance.
     */
    next(rawTimestampUs, nowMs = Date.now()) {
        const raw = BigInt(rawTimestampUs || 0);
        if (this._epochOffsetUs === null) {
            this._epochOffsetUs = BigInt(nowMs) * 1000n - raw;
        }
        let ts = raw + this._epochOffsetUs;
        if (ts <= this._lastFrameTs) ts = this._lastFrameTs + 1n;
        this._lastFrameTs = ts;
        return ts;
    }
}

module.exports = { FrameTimestampAnchor };
